import{_ as e,o,c as a,a0 as i}from"./chunks/framework.DW5bL-_G.js";const u=JSON.parse('{"title":"Comparison & Positioning","description":"How EW Color Picker compares with Pickr, iro.js, Coloris, react-colorful and react-color, and where it fits.","frontmatter":{"title":"Comparison & Positioning","description":"How EW Color Picker compares with Pickr, iro.js, Coloris, react-colorful and react-color, and where it fits."},"headers":[],"relativePath":"en/guide/comparison.md","filePath":"en/guide/comparison.md"}'),r={name:"en/guide/comparison.md"};function n(s,t,d,l,c,h){return o(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="comparison-positioning" tabindex="-1">Comparison &amp; Positioning <a class="header-anchor" href="#comparison-positioning" aria-label="Permalink to &quot;Comparison &amp; Positioning&quot;">​</a></h1><p>Choosing a color picker is rarely about feature count — it is about whether the component fits your UI system. This page states the positioning first, then compares the mainstream options, and finally explains when each one is the right call.</p><h2 id="positioning-in-one-sentence" tabindex="-1">Positioning in one sentence <a class="header-anchor" href="#positioning-in-one-sentence" aria-label="Permalink to &quot;Positioning in one sentence&quot;">​</a></h2><p>EW Color Picker is not a ready-made skin. It is an <strong>assemblable color picker foundation</strong>: the core only keeps color state and events, and every UI element is an independent plugin. Teams keep what they need, replace what they do not, or write their own UI on the same plugin contract.</p><p>Good fit: admin dashboards, low-code platforms, component libraries, and products that must merge deeply with an existing design system. Poor fit: a one-off color input where customization is unnecessary — the native <code>input[type=color]</code> or Coloris is simpler.</p><h2 id="side-by-side-comparison" tabindex="-1">Side-by-side comparison <a class="header-anchor" href="#side-by-side-comparison" aria-label="Permalink to &quot;Side-by-side comparison&quot;">​</a></h2><p>The numbers below come from the npm registry (<code>unpackedSize</code> and last publish date, collected on 2026-10-30) and are only a sense of package size. Feature columns follow each project&#39;s public documentation.</p><table tabindex="0"><thead><tr><th>Option</th><th>Shape</th><th>Framework lock-in</th><th>Extension model</th><th>Unpacked size</th><th>Last publish</th></tr></thead><tbody><tr><td><strong>EW Color Picker</strong></td><td>13 npm packages, plugin-based</td><td>None (plain DOM)</td><td>Plugin registration / custom plugins</td><td>Aggregate 543.8 KB; <code>core.min</code> 11 KB (gzip 3 KB)</td><td>2026-10</td></tr><tr><td><a href="https://github.com/Simonwep/pickr" target="_blank" rel="noreferrer">Pickr</a></td><td>Single package (UMD/ESM)</td><td>None</td><td>Themes (classic/monolith/nano) + options</td><td>280.3 KB</td><td>2026-09</td></tr><tr><td><a href="https://github.com/jaames/iro.js" target="_blank" rel="noreferrer">iro.js</a></td><td>Single package</td><td>None</td><td>Options + component composition</td><td>231.4 KB</td><td>2021-07</td></tr><tr><td><a href="https://github.com/melloware/coloris" target="_blank" rel="noreferrer">Coloris</a></td><td>Single package + CSS</td><td>None</td><td>CSS variables + options</td><td>152.2 KB</td><td>2026-10</td></tr><tr><td><a href="https://github.com/omgovich/react-colorful" target="_blank" rel="noreferrer">react-colorful</a></td><td>React components</td><td>React</td><td>Compose components</td><td>398.4 KB</td><td>2026-09</td></tr><tr><td><a href="https://github.com/casesandberg/react-color" target="_blank" rel="noreferrer">react-color</a></td><td>React component set</td><td>React</td><td>Pick a picker component</td><td>436.3 KB</td><td>2020-10</td></tr><tr><td><a href="https://github.com/linx4200/vue-color" target="_blank" rel="noreferrer">vue-color</a></td><td>Vue component set</td><td>Vue</td><td>Pick a picker component</td><td>391.5 KB</td><td>2025-10</td></tr><tr><td><a href="https://github.com/uiwjs/react-color" target="_blank" rel="noreferrer">@uiw/react-color</a></td><td>React component set</td><td>React</td><td>Import per component</td><td>210.8 KB</td><td>2026-05</td></tr><tr><td>Native <code>input[type=color]</code></td><td>Built into browsers</td><td>None</td><td>None (styling is not controllable)</td><td>0</td><td>with browser updates</td></tr><tr><td>Spectrum</td><td>jQuery plugin</td><td>jQuery</td><td>Options</td><td>1804.2 KB</td><td>2020-05</td></tr></tbody></table><p>One caveat: unpacked size is not runtime cost. Most of EW Color Picker&#39;s aggregate weight comes from three artifacts (UMD, UMD.min, ESM) plus <code>.d.ts</code> declarations. The smallest runtime you can ship is <code>index.min.js</code> at <strong>79 KB (gzip 18 KB)</strong>, or <strong>11 KB (gzip 3 KB)</strong> when using the core alone.</p><h2 id="where-ew-color-picker-stands-out" tabindex="-1">Where EW Color Picker stands out <a class="header-anchor" href="#where-ew-color-picker-stands-out" aria-label="Permalink to &quot;Where EW Color Picker stands out&quot;">​</a></h2><h3 id="_1-structural-replaceability-not-just-theming" tabindex="-1">1. Structural replaceability, not just theming <a class="header-anchor" href="#_1-structural-replaceability-not-just-theming" aria-label="Permalink to &quot;1. Structural replaceability, not just theming&quot;">​</a></h3><p>Most alternatives let you restyle the widget via themes, CSS variables or options while the structure stays fixed. EW Color Picker splits the trigger box, saturation panel, hue slider, alpha slider, text input, number input, buttons, predefined swatches and mode switcher into separate plugins. You decide which ones are registered, in what order, and whether your own plugin replaces them.</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ewColorPicker </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@ew-color-picker/core&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Panel </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@ew-color-picker/panel&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Hue </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@ew-color-picker/hue&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// register only what you need</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ewColorPicker.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Panel).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Hue)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_2-framework-agnostic" tabindex="-1">2. Framework agnostic <a class="header-anchor" href="#_2-framework-agnostic" aria-label="Permalink to &quot;2. Framework agnostic&quot;">​</a></h3><p>The core touches plain DOM and events only — no React, Vue or jQuery runtime. The same plugin contract can back React, Vue, Angular or low-code wrappers without maintaining a separate implementation per framework.</p><h3 id="_3-single-source-of-truth-with-per-instance-events" tabindex="-1">3. Single source of truth with per-instance events <a class="header-anchor" href="#_3-single-source-of-truth-with-per-instance-events" aria-label="Permalink to &quot;3. Single source of truth with per-instance events&quot;">​</a></h3><p>Every plugin changes color through <code>core.setColor()</code>, and the <code>change</code> event keeps the rest in sync, so there is never a second copy of the color state. Each instance owns its event bus, DOM and plugin instances, so multi-instance pages do not leak into each other.</p><h3 id="_4-complete-out-of-the-box" tabindex="-1">4. Complete out of the box <a class="header-anchor" href="#_4-complete-out-of-the-box" aria-label="Permalink to &quot;4. Complete out of the box&quot;">​</a></h3><p>The aggregate package ships Hex / RGB / HSL mode switching, alpha adjustment, predefined swatches, clear/confirm buttons and input validation — things you would otherwise assemble by hand on top of react-colorful.</p><h3 id="_5-typescript-types-everywhere" tabindex="-1">5. TypeScript types everywhere <a class="header-anchor" href="#_5-typescript-types-everywhere" aria-label="Permalink to &quot;5. TypeScript types everywhere&quot;">​</a></h3><p>Every package emits <code>.d.ts</code>; plugins extend the core options via <code>declare module</code>, so custom plugins keep type inference too.</p><h3 id="_6-documentation-as-part-of-the-product" tabindex="-1">6. Documentation as part of the product <a class="header-anchor" href="#_6-documentation-as-part-of-the-product" aria-label="Permalink to &quot;6. Documentation as part of the product&quot;">​</a></h3><p>Bilingual documentation, per-API references, one page per plugin, plus <code>llms.txt</code> / <code>llms-full.txt</code> so both people and AI can look things up.</p><h2 id="limitations-to-be-honest-about" tabindex="-1">Limitations to be honest about <a class="header-anchor" href="#limitations-to-be-honest-about" aria-label="Permalink to &quot;Limitations to be honest about&quot;">​</a></h2><ul><li><strong>Small ecosystem</strong>: download counts, community tutorials and issue history cannot match Pickr or react-color; unusual problems mean reading the source.</li><li><strong>No official framework wrappers</strong>: React and Vue users need a thin wrapper layer.</li><li><strong>No gradients, multi-color editing or eyedropper</strong>: those use cases need iro.js or a dedicated gradient picker.</li><li><strong>Many packages</strong>: onboarding requires understanding the core + plugins model.</li><li><strong>Absolute size is not a selling point</strong>: the aggregate package (543.8 KB, declarations and three artifacts included) is larger than Pickr or Coloris as a whole. The advantage is trimming it down.</li></ul><h2 id="choosing-the-right-tool" tabindex="-1">Choosing the right tool <a class="header-anchor" href="#choosing-the-right-tool" aria-label="Permalink to &quot;Choosing the right tool&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Your situation</th><th>Recommendation</th></tr></thead><tbody><tr><td>A plain color input; styling does not matter</td><td>Native <code>input[type=color]</code></td></tr><tr><td>Lightweight, dependency-free, themeable without structural changes</td><td>Coloris or Pickr</td></tr><tr><td>React project that only needs a panel or slider</td><td>react-colorful</td></tr><tr><td>Vue project that wants ready-made components</td><td>vue-color or @uiw/react-color</td></tr><tr><td>Gradients, color-space work, games or visualizations</td><td>iro.js</td></tr><tr><td>Admin / low-code / component library needing deep design-system integration, partial UI replacement and instance isolation</td><td><strong>EW Color Picker</strong></td></tr><tr><td>Embedding color selection into your own plugin system or runtime</td><td><strong>EW Color Picker</strong> (11 KB core, keep the core and write your own plugins)</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Introduction</a> — design principles and package layout</li><li><a href="./concepts">Core Concepts</a> — mount points, plugin order and events</li><li><a href="./plugin-dev">Writing a Plugin</a> — replace the built-in UI with your own</li></ul>`,29)])])}const g=e(r,[["render",n]]);export{u as __pageData,g as default};
